            check("real-file-roundtrip-schema-and-release-retention",()=>{var f=new Fixture();var d=f.Manager.Data.rankData;d.nick="恢复测试\n\"";d.url="https://example.invalid/a";d.VN_d=int.MaxValue;d.DN_t=-2;d.playNum=12;d.isGetWechatInfo=true;f.Pool.SaveData();Require(!f.Stored.Contains("Nickname")&&!f.Stored.Contains("HasWechatInfo")&&f.Stored.Contains("rankData"),"interface aliases excluded from LitJSON schema");var g=new Fixture(f.PathName);Require(g.Manager.Data.rankData.nick==d.nick&&g.Manager.Data.rankData.url==d.url&&g.Manager.Data.rankData.VN_d==int.MaxValue&&g.Manager.Data.rankData.DN_t==-2&&g.Manager.Data.rankData.playNum==12&&g.Manager.Data.rankData.isGetWechatInfo,"fresh independent backend read");var held=g.Manager.Data;g.Manager.OnRelease();Require(g.Manager.Data==held,"empty release retains data");});
