            check("response-installed-after-all-synchronous-requests",()=>{var f=new Fixture();int oldCalls=0;f.Transmitter.SendResponseCallback=()=>oldCalls++;f.Transmitter.Sending=()=>f.Transmitter.SendResponseCallback?.Invoke();f.Control.SendRank(false);Require(oldCalls==3&&f.Manager.Data.rankData.DN_t==0,"synchronous responses see only old callback");f.Transmitter.SendResponseCallback();Require(f.Manager.Data.rankData.DN_d==1&&f.Manager.Data.rankData.DN_w==1&&f.Manager.Data.rankData.DN_t==1,"new callback available after all requests");});
