            OutgameConfigDerivedIndexes.AppendChineseNames(f.Config.dicAIName,f.Config.ChineseNames);
            var runtime=new OutgameMatchRuntime(()=>f.Account.Statistics.Pool,()=>f.Config,f.Account.Host,f.Account.Services.Storage,f.Account.Services.Versions,f.Account.Host.Downloads.Add,()=>"fixture-openid",()=>8,()=>f.Messages,()=>f.Trace.Add("explicit-avatar-init"));
            var reg=runtime.Registration;var manager=reg.Create();manager.ParticipatesInSync=reg.AutoSyn;manager.CompressData=reg.CompressData;manager.OnInit();f.Account.Statistics.Pool.Managers[reg.SourceTypeIndex]=manager;
            runtime.BindController(f.Account.Page.Data.Registry);var control=(OutgameMatchControl)f.Account.Page.Data.Registry.Resolve(4129);control.OnInit();OutgameMatchRuntime.BindTopInfo(f.Services,()=>control);return control;
        }
